const item = $input.item.json;
const triggerData = $('Telegram Trigger').item.json;
const chatId = triggerData.message?.chat?.id;

let messageText = '';

if (!item || !item.answer) {
  messageText = '⚠️ *Sorry*, I could not retrieve an answer to your request. Please try again later.';
} else {
  messageText = `🤖 *Answer:*\n${item.answer}\n\n`;

  // Confidence badge
  const confidenceEmoji = item.confidence === 'high' ? '🟢' : (item.confidence === 'medium' ? '🟡' : '🔴');
  messageText += `📊 *Confidence:* ${confidenceEmoji} ${String(item.confidence || 'unknown').toUpperCase()}\n`;

  // Sources & Citations
  if (item.sources && item.sources.length > 0) {
    messageText += `\n📚 *Sources & Citations:*\n`;
    item.sources.forEach((source, index) => {
      const pageStr = source.page_number ? ` (Page ${source.page_number})` : '';
      const scorePercent = Math.round((source.similarity_score || 0) * 100);
      messageText += `\n*${index + 1}.* 📄 \`${source.document_name}\`${pageStr} — _Similarity: ${scorePercent}%_\n`;
      if (source.excerpt) {
        const cleanExcerpt = source.excerpt.replace(/\s+/g, ' ').slice(0, 180);
        messageText += `> _"${cleanExcerpt}"..._\n`;
      }
    });
  }
}

return {
  json: {
    chatId: chatId,
    text: messageText
  }
};
